import {totals,today,roundCents} from './model.js?v=analysis-1';
export const cents=roundCents;
export const currency=v=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',useGrouping:'always'}).format(v/100);
export const active=(i,asOf=today())=>(i.date||'0001-01-01')<=asOf&&(!i.voidDate||i.voidDate>asOf);
export function invoiceTotal(i){if(i.historicalTotals)return {...i.historicalTotals,withholdingCents:i.historicalTotals.withholdingCents||0};const t=totals(i);return {baseCents:cents(t.base),vatCents:cents(t.vat),withholdingCents:cents(t.withholding||0),totalCents:cents(t.total)};}
export function initializeLedger(db){for(const key of ['payments','allocations','adjustments','refunds','paymentAdjustments','importBatches'])db[key]??=[];db.financeVersion??=1;return db;}
export function balances(db,asOf=today(),includeDemo=false){const issued=new Map(db.invoices.filter(i=>i.status==='issued'&&i.date<=asOf&&!i.voided&&(includeDemo||!i.isDemo)).map(i=>[i.id,i])),groups=new Map();
 for(const i of issued.values()){let root=i,depth=0;const seen=new Set([i.id]);while(issued.has(root.originalId)&&!seen.has(root.originalId)){root=issued.get(root.originalId);seen.add(root.id);depth++;}if(!groups.has(root.id))groups.set(root.id,{root,members:[],current:i,depth});const g=groups.get(root.id);g.members.push(i);if(depth>g.depth||(depth===g.depth&&i.date>g.current.date)){g.current=i;g.depth=depth;}}
 const payments=new Set(db.payments.filter(p=>active(p,asOf)).map(p=>p.id));
 return [...groups.values()].map(g=>{const ids=new Set(g.members.map(i=>i.id)),t=invoiceTotal(g.current);const applied=db.allocations.filter(a=>ids.has(a.invoiceId)&&payments.has(a.paymentId)&&active(a,asOf));const adjustments=db.adjustments.filter(a=>ids.has(a.invoiceId)&&active(a,asOf));const refunds=db.refunds.filter(r=>ids.has(r.invoiceId)&&active(r,asOf));const paid=applied.reduce((n,a)=>n+a.amountCents,0)-refunds.reduce((n,a)=>n+a.amountCents,0),adjusted=adjustments.reduce((n,a)=>n+a.amountCents,0),pending=t.totalCents-paid-adjusted;
 return {rootId:g.root.id,invoice:g.current,original:g.root,memberIds:[...ids],...t,paidCents:paid,adjustedCents:adjusted,pendingCents:Math.max(0,pending),creditCents:Math.max(0,-pending),status:pending<=0?'paid':paid+adjusted>0?'partial':'unpaid',applied,adjustments,refunds};});
}
export function available(db,payment,asOf=today()){if(payment.restricted||!active(payment,asOf))return 0;return payment.amountCents-db.allocations.filter(a=>a.paymentId===payment.id&&active(a,asOf)).reduce((n,a)=>n+a.amountCents,0)-db.refunds.filter(a=>a.paymentId===payment.id&&!a.invoiceId&&active(a,asOf)).reduce((n,a)=>n+a.amountCents,0)-db.paymentAdjustments.filter(a=>a.paymentId===payment.id&&active(a,asOf)).reduce((n,a)=>n+a.amountCents,0);}
export function periodBounds(mode,year,month,quarter,start,end){if(mode==='custom')return {start,end};if(mode==='month'){const y=Number(year),m=Number(month);return {start:`${year}-${String(m).padStart(2,'0')}-01`,end:new Date(Date.UTC(y,m,0)).toISOString().slice(0,10)};}if(mode==='quarter'){const m=(Number(quarter)-1)*3+1;return {start:`${year}-${String(m).padStart(2,'0')}-01`,end:new Date(Date.UTC(Number(year),m+2,0)).toISOString().slice(0,10)};}return {start:`${year}-01-01`,end:`${year}-12-31`};}
export function summary(db,range,asOf=today(),clientId='',includeDemo=false){const all=balances(db,asOf,includeDemo),matches=b=>!clientId||b.invoice.clientId===clientId;const cohort=all.filter(b=>b.original.date>=range.start&&b.original.date<=range.end&&matches(b));return {all:all.filter(matches),cohort,baseCents:cohort.reduce((n,b)=>n+b.baseCents,0),vatCents:cohort.reduce((n,b)=>n+b.vatCents,0),withholdingCents:cohort.reduce((n,b)=>n+b.withholdingCents,0),totalCents:cohort.reduce((n,b)=>n+b.totalCents,0),paidCents:cohort.reduce((n,b)=>n+b.paidCents,0),adjustedCents:cohort.reduce((n,b)=>n+b.adjustedCents,0),pendingCents:cohort.reduce((n,b)=>n+b.pendingCents,0),pendingAllCents:all.filter(matches).reduce((n,b)=>n+b.pendingCents,0),creditAllCents:all.filter(matches).reduce((n,b)=>n+b.creditCents,0)};}
export function paymentAmount(db,payment,asOf=today()){return payment.restricted?db.allocations.filter(a=>a.paymentId===payment.id&&active(a,asOf)).reduce((n,a)=>n+a.amountCents,0):payment.amountCents;}
export function cashTotal(db,start,end,asOf=today()){return db.payments.filter(p=>active(p,asOf)&&p.date>=start&&p.date<=end).reduce((n,p)=>n+paymentAmount(db,p,asOf),0)-db.refunds.filter(r=>active(r,asOf)&&r.date>=start&&r.date<=end).reduce((n,r)=>n+r.amountCents,0);}

export const paymentName=payment=>payment.name?.trim()||payment.reference?.trim()||payment.payer||'Pago sin nombre';
export function invoicePayments(db,balance,asOf=today()){
 const byPayment=new Map();
 for(const a of balance.applied){const payment=db.payments.find(p=>p.id===a.paymentId);if(!payment||!active(payment,asOf))continue;if(!byPayment.has(payment.id))byPayment.set(payment.id,{payment,name:paymentName(payment),amountCents:0});byPayment.get(payment.id).amountCents+=a.amountCents;}
 for(const r of balance.refunds){const entry=byPayment.get(r.paymentId);if(entry)entry.amountCents-=r.amountCents;}
 return [...byPayment.values()].filter(p=>p.amountCents>0).sort((a,b)=>a.payment.date.localeCompare(b.payment.date));
}
